//! Error types for Bivvy operations.
//!
//! This module defines [`BivvyError`], the primary error type used throughout
//! the application, and a [`Result`] type alias for convenience.
//!
//! # Error Handling Strategy
//!
//! - Use `BivvyError` for domain-specific errors that need distinct handling
//! - Use `anyhow::Error` (via `BivvyError::Other`) for unexpected errors
//! - All errors should provide actionable messages for users

use std::path::PathBuf;
use thiserror::Error;

/// Core error type for Bivvy operations.
#[derive(Debug, Error)]
pub enum BivvyError {
    /// Configuration file not found at expected location.
    #[error("Configuration not found: {path}")]
    ConfigNotFound { path: PathBuf },

    /// Failed to parse configuration file.
    #[error("Failed to parse config at {path}: {message}")]
    ConfigParseError { path: PathBuf, message: String },

    /// Invalid configuration structure or values.
    #[error("Invalid configuration: {message}")]
    ConfigValidationError { message: String },

    /// Referenced template does not exist.
    #[error("Unknown template: {name}")]
    UnknownTemplate { name: String },

    /// Step dependency cycle detected.
    #[error("Circular dependency detected: {cycle}")]
    CircularDependency { cycle: String },

    /// Step execution failed.
    #[error("Step '{step}' failed: {message}")]
    StepExecutionError { step: String, message: String },

    /// Shell command failed.
    #[error("Command failed with exit code {code:?}: {command}")]
    CommandFailed { command: String, code: Option<i32> },

    /// A required tool or service is missing and cannot be auto-installed.
    #[error("Missing requirement '{requirement}': {message}")]
    RequirementMissing {
        requirement: String,
        message: String,
    },

    /// A requirement check failed unexpectedly (e.g., network error during install).
    #[error("Requirement check failed for '{requirement}': {message}")]
    RequirementCheckFailed {
        requirement: String,
        message: String,
    },

    /// An untrusted remote URL was encountered in non-interactive mode.
    #[error("Untrusted remote config URL: {url}. Use --trust to auto-approve or run interactively to confirm.")]
    UntrustedUrl { url: String },

    /// Shell operation failed (e.g., spawning a debug shell).
    #[error("Shell error: {message}")]
    ShellError { message: String },

    /// IO error wrapper.
    #[error("IO error: {0}")]
    Io(#[from] std::io::Error),

    /// Generic wrapped error for anyhow interop.
    #[error(transparent)]
    Other(#[from] anyhow::Error),
}

/// Result type alias for Bivvy operations.
pub type Result<T> = std::result::Result<T, BivvyError>;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn config_not_found_displays_path() {
        let err = BivvyError::ConfigNotFound {
            path: PathBuf::from("/foo/bar.yml"),
        };
        assert!(err.to_string().contains("/foo/bar.yml"));
    }

    #[test]
    fn config_parse_error_displays_path_and_message() {
        let err = BivvyError::ConfigParseError {
            path: PathBuf::from("/config.yml"),
            message: "invalid syntax".into(),
        };
        let msg = err.to_string();
        assert!(msg.contains("/config.yml"));
        assert!(msg.contains("invalid syntax"));
    }

    #[test]
    fn config_validation_error_displays_message() {
        let err = BivvyError::ConfigValidationError {
            message: "missing required field".into(),
        };
        assert!(err.to_string().contains("missing required field"));
    }

    #[test]
    fn unknown_template_displays_name() {
        let err = BivvyError::UnknownTemplate {
            name: "nonexistent".into(),
        };
        assert!(err.to_string().contains("nonexistent"));
    }

    #[test]
    fn circular_dependency_displays_cycle() {
        let err = BivvyError::CircularDependency {
            cycle: "a → b → a".into(),
        };
        assert!(err.to_string().contains("a → b → a"));
    }

    #[test]
    fn step_execution_error_displays_step_and_message() {
        let err = BivvyError::StepExecutionError {
            step: "install_deps".into(),
            message: "npm not found".into(),
        };
        let msg = err.to_string();
        assert!(msg.contains("install_deps"));
        assert!(msg.contains("npm not found"));
    }

    #[test]
    fn command_failed_displays_command_and_code() {
        let err = BivvyError::CommandFailed {
            command: "npm install".into(),
            code: Some(1),
        };
        let msg = err.to_string();
        assert!(msg.contains("npm install"));
        assert!(msg.contains("1"));
    }

    #[test]
    fn requirement_missing_displays_requirement_and_message() {
        let err = BivvyError::RequirementMissing {
            requirement: "ruby".into(),
            message: "Not found on PATH".into(),
        };
        let msg = err.to_string();
        assert!(msg.contains("ruby"));
        assert!(msg.contains("Not found on PATH"));
    }

    #[test]
    fn requirement_check_failed_displays_requirement_and_message() {
        let err = BivvyError::RequirementCheckFailed {
            requirement: "node".into(),
            message: "Install command exited with code 1".into(),
        };
        let msg = err.to_string();
        assert!(msg.contains("node"));
        assert!(msg.contains("Install command exited with code 1"));
    }

    #[test]
    fn untrusted_url_displays_url_and_hint() {
        let err = BivvyError::UntrustedUrl {
            url: "https://example.com/config.yml".into(),
        };
        let msg = err.to_string();
        assert!(msg.contains("https://example.com/config.yml"));
        assert!(msg.contains("--trust"));
    }

    #[test]
    fn io_error_converts_from_std() {
        let io_err = std::io::Error::new(std::io::ErrorKind::NotFound, "file missing");
        let err: BivvyError = io_err.into();
        assert!(matches!(err, BivvyError::Io(_)));
    }

    #[test]
    fn result_type_alias_works() {
        fn returns_error() -> Result<()> {
            Err(BivvyError::ConfigValidationError {
                message: "test".into(),
            })
        }
        assert!(returns_error().is_err());
    }
}

//! Configuration schema definitions for Bivvy.
//!
//! This module contains all the struct definitions that map to
//! the YAML configuration file format.

use crate::checks::{Check, SatisfactionCondition};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;

/// Helper for `serde_yaml::Value` fields — accepts any valid YAML/JSON value.
fn any_value_schema(_: &mut schemars::generate::SchemaGenerator) -> schemars::Schema {
    true.into()
}

/// Helper for `HashMap<String, serde_yaml::Value>` — object with any values.
fn any_value_map_schema(_: &mut schemars::generate::SchemaGenerator) -> schemars::Schema {
    let mut map = serde_json::Map::new();
    map.insert(
        "type".to_string(),
        serde_json::Value::String("object".to_string()),
    );
    map.insert(
        "additionalProperties".to_string(),
        serde_json::Value::Bool(true),
    );
    map.into()
}

/// Root configuration structure for bivvy.yml
#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct BivvyConfig {
    /// Application name (for display purposes)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub app_name: Option<String>,

    /// Global settings
    pub settings: Settings,

    /// Remote template sources
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub template_sources: Vec<TemplateSource>,

    /// Step definitions
    #[serde(default)]
    pub steps: HashMap<String, StepConfig>,

    /// Workflow definitions
    #[serde(default)]
    pub workflows: HashMap<String, WorkflowConfig>,

    /// Secrets configuration
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub secrets: HashMap<String, SecretConfig>,

    /// Config inheritance
    #[serde(skip_serializing_if = "Option::is_none")]
    pub extends: Option<Vec<ExtendsConfig>>,

    /// Custom requirement definitions
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub requirements: HashMap<String, CustomRequirement>,

    /// User-defined variables for interpolation.
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub vars: HashMap<String, VarDefinition>,
}

/// JSONL event logging settings.
///
/// Controls whether structured event logs are written to `~/.bivvy/logs/`
/// and how long they are retained.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(default)]
pub struct LoggingSettings {
    /// Enable JSONL event logging. When false, no log files are written.
    #[serde(default = "default_true", skip_serializing_if = "is_true")]
    pub logging: bool,

    /// Maximum age of log files in days. Files older than this are deleted
    /// during cleanup. Default: 30.
    #[serde(
        default = "default_log_retention_days",
        skip_serializing_if = "is_default_log_retention_days"
    )]
    pub log_retention_days: u32,

    /// Maximum total size of log files in megabytes. When exceeded, oldest
    /// files are deleted first. Default: 500.
    #[serde(
        default = "default_log_retention_mb",
        skip_serializing_if = "is_default_log_retention_mb"
    )]
    pub log_retention_mb: u64,
}

impl Default for LoggingSettings {
    fn default() -> Self {

