45	            success: true,
46	            exit_code: 0,
47	        }
48	    }
49	
50	    /// Create a failure result.
51	    pub fn failure(exit_code: i32) -> Self {
52	        Self {
53	            success: false,
54	            exit_code,
55	        }
56	    }
57	}
