181	impl Command for ListCommand {
182	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
183	        // Load configuration via the appropriate strategy (discovery vs full
184	        // merge vs single-target detail view).
185	        let discovery = Discovery::new(&self.project_root);
186	        let has_any_project_files = discovery.project_config_path().is_some()
187	            || !discovery.workflow_files().is_empty()
188	            || !discovery.step_files().is_empty()
189	            || self.config_override.is_some();
190	        if !has_any_project_files {
191	            ui.error("No configuration found. Run 'bivvy init' first.");
192	            return Ok(CommandResult::failure(2));
193	        }
194	
195	        let config = match self.build_view() {
196	            Ok(c) => c,
197	            Err(BivvyError::ConfigNotFound { .. }) => {
198	                ui.error("No configuration found. Run 'bivvy init' first.");
199	                return Ok(CommandResult::failure(2));
200	            }
201	            Err(BivvyError::ConfigValidationError { message }) => {
202	                ui.error(&message);
203	                return Ok(CommandResult::failure(1));
204	            }
205	            Err(e) => return Err(e),
206	        };
207	
208	        // Apply config default_output when no CLI flag was explicitly set
209	        if ui.output_mode() == OutputMode::Normal {
210	            ui.set_output_mode(config.settings.defaults.output.into());
211	        }
212	
213	        let theme = BivvyTheme::new();
214	
215	        // Resolve environment
216	        let resolved_env = self.resolve_environment(&config);
217	        let env_name = &resolved_env.name;
218	
219	        // JSON output mode
220	        if self.args.json {
221	            let steps = if !self.args.workflows_only {
222	                let mut entries: Vec<StepJsonEntry> = config
223	                    .steps
224	                    .iter()
225	                    .map(|(name, step)| {
226	                        let skipped = !step.scoping.only_environments.is_empty()
227	                            && !step.scoping.only_environments.iter().any(|e| e == env_name);
228	                        StepJsonEntry {
229	                            name: name.clone(),
230	                            template: step.template.clone(),
231	                            command: step.execution.command.clone(),
232	                            description: step.description.clone(),
233	                            title: step.title.clone(),
234	                            depends_on: step.depends_on.clone(),
235	                            skipped,
236	                        }
237	                    })
238	                    .collect();
239	                entries.sort_by(|a, b| a.name.cmp(&b.name));
240	                Some(entries)
241	            } else {
242	                None
243	            };
244	
245	            let workflows = if !self.args.steps_only {
246	                let mut entries: Vec<WorkflowJsonEntry> = config
247	                    .workflows
248	                    .iter()
249	                    .map(|(name, workflow)| WorkflowJsonEntry {
250	                        name: name.clone(),
251	                        steps: workflow.steps.clone(),
252	                        description: workflow.description.clone(),
253	                    })
254	                    .collect();
255	                entries.sort_by(|a, b| a.name.cmp(&b.name));
256	                Some(entries)
257	            } else {
258	                None
259	            };
260	
261	            let output = ListJsonOutput {
262	                environment: Some(env_name.clone()),
263	                steps,
264	                workflows,
265	            };
266	
267	            let json = serde_json::to_string_pretty(&output).map_err(|e| {
268	                BivvyError::ConfigValidationError {
269	                    message: format!("JSON serialization failed: {}", e),
270	                }
271	            })?;
272	            ui.message(&json);
273	            return Ok(CommandResult::success());
274	        }
275	
276	        // Show environment info
277	        ui.message(&format!(
278	            "  {} {} ({})\n",
279	            theme.key.apply_to("Environment:"),
280	            theme.highlight.apply_to(env_name),
281	            theme.dim.apply_to(resolved_env.source.to_string()),
282	        ));
283	
284	        // Show steps
285	        if !self.args.workflows_only {
286	            ui.message(&format!("  {}", theme.key.apply_to("Steps:")));
287	            for (name, step) in &config.steps {
288	                // Check if step is skipped by only_environments
289	                let skipped = !step.scoping.only_environments.is_empty()
290	                    && !step.scoping.only_environments.iter().any(|e| e == env_name);
291	
292	                if skipped {
293	                    ui.message(&format!(
294	                        "    {} {}",
295	                        theme.dim.apply_to(name),
296	                        theme.dim.apply_to(format!("(skipped in {})", env_name)),
297	                    ));
298	                    continue;
299	                }
300	
301	                // First line: step name with template/command detail
302	                let detail = if let Some(ref template) = step.template {
303	                    format!(
304	                        " {}",
305	                        theme.dim.apply_to(format!("(template: {})", template))
306	                    )
307	                } else if let Some(ref cmd) = step.execution.command {
308	                    format!(
309	                        " {} {}",
310	                        theme.dim.apply_to("—"),
311	                        theme.command.apply_to(cmd)
312	                    )
313	                } else {
314	                    String::new()
315	                };
316	                ui.message(&format!("    {}{}", theme.highlight.apply_to(name), detail));
317	
318	                // Description or title
319	                if let Some(ref desc) = step.description {
320	                    ui.message(&format!("      {}", theme.dim.apply_to(desc)));
321	                } else if let Some(ref title) = step.title {
322	                    ui.message(&format!("      {}", theme.dim.apply_to(title)));
323	                }
324	
325	                // Dependency tree
326	                if !step.depends_on.is_empty() {
327	                    ui.message(&format!(
328	                        "      {} {}",
329	                        theme.dim.apply_to("└── depends on:"),
330	                        theme.dim.apply_to(step.depends_on.join(", "))
331	                    ));
332	                }
333	            }
334	
335	            if !self.args.steps_only {
336	                ui.message("");
337	            }
338	        }
339	
340	        // Show workflows
341	        if !self.args.steps_only {
342	            ui.message(&format!("  {}", theme.key.apply_to("Workflows:")));
343	            for (name, workflow) in &config.workflows {
344	                let arrow_steps = workflow.steps.join(" → ");
345	                ui.message(&format!(
346	                    "    {}{} {}",
347	                    theme.highlight.apply_to(name),
348	                    theme.dim.apply_to(":"),
349	                    theme.dim.apply_to(&arrow_steps),
350	                ));
351	
352	                if let Some(ref desc) = workflow.description {
353	                    ui.message(&format!("      {}", theme.dim.apply_to(desc)));
354	                }
355	            }
356	        }
357	
358	        Ok(CommandResult::success())
359	    }
360	}
